values
  ('CAL-OBS-01-01', 'Tết Dương lịch (Mốc chính thức)', 'New Year''s Day (Official Observance)', 'Ngày nghỉ lễ chính thức đầu năm; hỗ trợ kế hoạch giao nhận hộp quà NaiBox đầu xuân. Nguồn: Bộ luật Lao động 2019 (Nghỉ lễ chính thức).', 'Official public holiday; schedule early orchard pickup before January 1. Source: Bộ luật Lao động 2019 (Nghỉ lễ chính thức).', 'observance', 'official_observance', 'Bộ luật Lao động 2019 (Nghỉ lễ chính thức)', 'scheduled', '2027-01-01T00:00:00+07:00', '2027-01-01T23:59:00+07:00', true, 'Asia/Ho_Chi_Minh', , 'high', 'public', , , , , '/events?tab=holidays', , 'Toàn quốc / Thành phố Đồng Nai', true),
  ('CAL-OBS-03-08', 'Ngày Quốc tế Phụ nữ (Mốc chính thức)', 'International Women''s Day (Official Observance)', 'Tôn vinh nữ chủ thể OCOP & tổ phụ nữ sơ chế đặc sản Đồng Nai. Nguồn: United Nations Observances.', 'Honoring women orchard owners and cooperative processing teams. Source: United Nations Observances.', 'observance', 'official_observance', 'United Nations Observances', 'completed', '2026-03-08T00:00:00+07:00', '2026-03-08T23:59:00+07:00', true, 'Asia/Ho_Chi_Minh', , 'high', 'public', , , , , '/events?tab=holidays', , 'Toàn quốc / Thành phố Đồng Nai', true),
  ('CAL-OBS-03-26', 'Ngày Thành lập Đoàn TNCS Hồ Chí Minh (Mốc chính thức)', 'Ho Chi Minh Communist Youth Union Founding Day (Official Observance)', 'Ngày hội ra quân đội hình Thanh niên Tình nguyện Số hỗ trợ nhà vườn. Nguồn: Mốc kỷ niệm lịch sử Đoàn Thanh niên Việt Nam.', 'Annual Youth Digital Volunteering kickoff honoring youth-farmer partnerships. Source: Mốc kỷ niệm lịch sử Đoàn Thanh niên Việt Nam.', 'observance', 'official_observance', 'Mốc kỷ niệm lịch sử Đoàn Thanh niên Việt Nam', 'completed', '2026-03-26T00:00:00+07:00', '2026-03-26T23:59:00+07:00', true, 'Asia/Ho_Chi_Minh', , 'high', 'public', , , , , '/events?tab=holidays', , 'Toàn quốc / Thành phố Đồng Nai', true),
  ('CAL-OBS-04-30', 'Ngày Giải phóng miền Nam & Quốc tế Lao động (30/4 – 01/5) (Mốc chính thức)', 'Reunification Day & International Labor Day (Official Observance)', 'Kỳ nghỉ lễ chính thức — cần kiểm tra lịch nhân sự giao nhận và ca đón khách vườn. Nguồn: Bộ luật Lao động 2019.', 'Official holiday period requiring orchard tour capacity & fulfillment scheduling. Source: Bộ luật Lao động 2019.', 'observance', 'official_observance', 'Bộ luật Lao động 2019', 'completed', '2026-04-30T00:00:00+07:00', '2026-04-30T23:59:00+07:00', true, 'Asia/Ho_Chi_Minh', , 'high', 'public', , , , , '/events?tab=holidays', , 'Toàn quốc / Thành phố Đồng Nai', true),
  ('CAL-OBS-06-05', 'Ngày Môi trường Thế giới (Mốc chính thức)', 'World Environment Day (Official Observance)', 'Thực hành bao bì tre rơm giảm nhựa & câu chuyện canh tác bền vững (không greenwashing). Nguồn: United Nations Environment Programme.', 'Highlighting biodegradable bamboo/straw packing and real farm stewardship. Source: United Nations Environment Programme.', 'observance', 'official_observance', 'United Nations Environment Programme', 'completed', '2026-06-05T00:00:00+07:00', '2026-06-05T23:59:00+07:00', true, 'Asia/Ho_Chi_Minh', , 'high', 'public', , , , , '/events?tab=holidays', , 'Toàn quốc / Thành phố Đồng Nai', true),
  ('CAL-OBS-09-02', 'Ngày Quốc khánh nước CHXHCN Việt Nam (Mốc chính thức)', 'Vietnam National Day (Official Observance)', 'Áp dụng nhận diện cờ Tổ quốc trang trọng trong dịp lễ Quốc gia. Nguồn: Bộ luật Lao động 2019.', 'National observance featuring respectful heritage & orchard showcase stories. Source: Bộ luật Lao động 2019.', 'observance', 'official_observance', 'Bộ luật Lao động 2019', 'completed', '2026-09-02T00:00:00+07:00', '2026-09-02T23:59:00+07:00', true, 'Asia/Ho_Chi_Minh', , 'high', 'public', , , , , '/events?tab=holidays', , 'Toàn quốc / Thành phố Đồng Nai', true),
  ('CAL-OBS-09-29', 'Ngày Quốc tế Nhận thức về Thất thoát và Lãng phí Thực phẩm (Mốc chính thức)', 'International Day of Awareness of Food Loss and Waste (Official Observance)', 'Gắn phân hệ NaiRescue cứu nông sản chín rộ đủ điều kiện an toàn và kế hoạch thu hoạch. Nguồn: FAO / United Nations.', 'Connects NaiRescue surplus fruit conservation and FEFO cold-storage planning. Source: FAO / United Nations.', 'observance', 'official_observance', 'FAO / United Nations', 'completed', '2026-09-29T00:00:00+07:00', '2026-09-29T23:59:00+07:00', true, 'Asia/Ho_Chi_Minh', , 'high', 'public', , , , , '/events?tab=holidays', , 'Toàn quốc / Thành phố Đồng Nai', true),
  ('CAL-OBS-10-16', 'Ngày Lương thực Thế giới (Mốc chính thức)', 'World Food Day (Official Observance)', 'Nêu bật hành trình minh bạch từ nhà vườn Đồng Nai tới bữa ăn gia đình qua mã QR. Nguồn: Food and Agriculture Organization (FAO).', 'Celebrating transparent orchard-to-table food security via QR traceability. Source: Food and Agriculture Organization (FAO).', 'observance', 'official_observance', 'Food and Agriculture Organization (FAO)', 'completed', '2026-10-16T00:00:00+07:00', '2026-10-16T23:59:00+07:00', true, 'Asia/Ho_Chi_Minh', , 'high', 'public', , , , , '/events?tab=holidays', , 'Toàn quốc / Thành phố Đồng Nai', true),
  ('CAL-OBS-11-23', 'Ngày Di sản văn hóa Việt Nam (Mốc chính thức)', 'Vietnam Cultural Heritage Day (Official Observance)', 'Ngày kỷ niệm văn hóa (không phải ngày nghỉ hưởng lương); tôn vinh làng bưởi Tân Triều và nghề rang củi Xuân Lộc. Nguồn: QĐ 36/2005/QĐ-TTg của Thủ tướng Chính phủ.', 'National heritage observance honoring Tan Trieu pomelo villages and traditional craft stories. Source: QĐ 36/2005/QĐ-TTg của Thủ tướng Chính phủ.', 'observance', 'official_observance', 'QĐ 36/2005/QĐ-TTg của Thủ tướng Chính phủ', 'completed', '2026-11-23T00:00:00+07:00', '2026-11-23T23:59:00+07:00', true, 'Asia/Ho_Chi_Minh', , 'high', 'public', , , , , '/events?tab=holidays', , 'Toàn quốc / Thành phố Đồng Nai', true),
  ('CAL-OBS-11-24', 'Ngày Văn hóa Việt Nam (Mốc chính thức)', 'Vietnam Culture Day (Official Observance)', 'Mốc ngày 24/11/2026 đã qua theo đồng hồ hệ thống 25/11/2026 — chiến dịch kỷ niệm hiển thị ở chế độ Tóm tắt lại (Recap). Nguồn: Kế hoạch thực hiện QĐ 1111/QĐ-TTg (19/06/2026) — Cổng Thông tin Chính phủ.', 'Observed annually on Nov 24 (past relative to Nov 25, 2026 reference clock — displayed as Recap). Source: Kế hoạch thực hiện QĐ 1111/QĐ-TTg (19/06/2026) — Cổng Thông tin Chính phủ.', 'observance', 'official_observance', 'Kế hoạch thực hiện QĐ 1111/QĐ-TTg (19/06/2026) — Cổng Thông tin Chính phủ', 'completed', '2026-11-24T00:00:00+07:00', '2026-11-24T23:59:00+07:00', true, 'Asia/Ho_Chi_Minh', , 'high', 'public', , , , , '/events?tab=holidays', , 'Toàn quốc / Thành phố Đồng Nai', true),
  ('CAL-OBS-12-05', 'Ngày Quốc tế Tình nguyện & Ngày Đất thế giới (Mốc chính thức)', 'International Volunteer Day & World Soil Day (Official Observance)', 'Cả hai ngày quốc tế cùng rơi vào 05/12 — NaiFarm đề xuất chuỗi hoạt động ''Ngày hội Nông sản & Thanh niên Đồng Nai'' (do NaiFarm tự tổ chức). Nguồn: UN International Volunteer Day & FAO World Soil Day.', 'Both UN & FAO observances fall on Dec 5 — aligned with NaiFarm''s self-organized Youth & Soil showcase. Source: UN International Volunteer Day & FAO World Soil Day.', 'observance', 'official_observance', 'UN International Volunteer Day & FAO World Soil Day', 'scheduled', '2026-12-05T00:00:00+07:00', '2026-12-05T23:59:00+07:00', true, 'Asia/Ho_Chi_Minh', , 'high', 'public', , , , , '/events?tab=holidays', , 'Toàn quốc / Thành phố Đồng Nai', true),
