values
  ('OBS-01-01', 'Tết Dương lịch', 'New Year''s Day', '01/01 hằng năm', '01-01', false, 2026, 'Bộ luật Lao động 2019 (Nghỉ lễ chính thức)', 'https://thuvienphapluat.vn/', 'vietnam_official', 'Ngày nghỉ lễ chính thức đầu năm; hỗ trợ kế hoạch giao nhận hộp quà NaiBox đầu xuân.', 'Official public holiday; schedule early orchard pickup before January 1.', true),
  ('OBS-03-08', 'Ngày Quốc tế Phụ nữ', 'International Women''s Day', '08/03 hằng năm', '03-08', false, 2026, 'United Nations Observances', 'https://www.un.org/en/observances/list-days-weeks', 'un_fao', 'Tôn vinh nữ chủ thể OCOP & tổ phụ nữ sơ chế đặc sản Đồng Nai.', 'Honoring women orchard owners and cooperative processing teams.', true),
  ('OBS-03-26', 'Ngày Thành lập Đoàn TNCS Hồ Chí Minh', 'Ho Chi Minh Communist Youth Union Founding Day', '26/03 hằng năm', '03-26', false, 2026, 'Mốc kỷ niệm lịch sử Đoàn Thanh niên Việt Nam', 'https://doanthanhnien.vn/', 'vietnam_official', 'Ngày hội ra quân đội hình Thanh niên Tình nguyện Số hỗ trợ nhà vườn.', 'Annual Youth Digital Volunteering kickoff honoring youth-farmer partnerships.', true),
  ('OBS-04-30', 'Ngày Giải phóng miền Nam & Quốc tế Lao động (30/4 – 01/5)', 'Reunification Day & International Labor Day', '30/04 – 01/05 hằng năm', '04-30', false, 2026, 'Bộ luật Lao động 2019', 'https://thuvienphapluat.vn/', 'vietnam_official', 'Kỳ nghỉ lễ chính thức — cần kiểm tra lịch nhân sự giao nhận và ca đón khách vườn.', 'Official holiday period requiring orchard tour capacity & fulfillment scheduling.', true),
  ('OBS-06-05', 'Ngày Môi trường Thế giới', 'World Environment Day', '05/06 hằng năm', '06-05', false, 2026, 'United Nations Environment Programme', 'https://www.un.org/en/observances/list-days-weeks', 'un_fao', 'Thực hành bao bì tre rơm giảm nhựa & câu chuyện canh tác bền vững (không greenwashing).', 'Highlighting biodegradable bamboo/straw packing and real farm stewardship.', true),
  ('OBS-09-02', 'Ngày Quốc khánh nước CHXHCN Việt Nam', 'Vietnam National Day', '02/09 hằng năm', '09-02', false, 2026, 'Bộ luật Lao động 2019', 'https://baochinhphu.vn/', 'vietnam_official', 'Áp dụng nhận diện cờ Tổ quốc trang trọng trong dịp lễ Quốc gia.', 'National observance featuring respectful heritage & orchard showcase stories.', true),
  ('OBS-09-29', 'Ngày Quốc tế Nhận thức về Thất thoát và Lãng phí Thực phẩm', 'International Day of Awareness of Food Loss and Waste', '29/09 hằng năm', '09-29', false, 2026, 'FAO / United Nations', 'https://www.un.org/en/observances/list-days-weeks', 'un_fao', 'Gắn phân hệ NaiRescue cứu nông sản chín rộ đủ điều kiện an toàn và kế hoạch thu hoạch.', 'Connects NaiRescue surplus fruit conservation and FEFO cold-storage planning.', true),
  ('OBS-10-16', 'Ngày Lương thực Thế giới', 'World Food Day', '16/10 hằng năm', '10-16', false, 2026, 'Food and Agriculture Organization (FAO)', 'https://www.fao.org/', 'un_fao', 'Nêu bật hành trình minh bạch từ nhà vườn Đồng Nai tới bữa ăn gia đình qua mã QR.', 'Celebrating transparent orchard-to-table food security via QR traceability.', true),
  ('OBS-11-23', 'Ngày Di sản văn hóa Việt Nam', 'Vietnam Cultural Heritage Day', '23/11 hằng năm', '11-23', false, 2026, 'QĐ 36/2005/QĐ-TTg của Thủ tướng Chính phủ', 'https://thuvienphapluat.vn/phap-luat/ho-tro-phap-luat/ngay-di-san-van-hoa-viet-nam-la-ngay-nao-2026-ngay-di-san-van-hoa-viet-nam-co-duoc-nghi-khong-303319.html', 'vietnam_official', 'Ngày kỷ niệm văn hóa (không phải ngày nghỉ hưởng lương); tôn vinh làng bưởi Tân Triều và nghề rang củi Xuân Lộc.', 'National heritage observance honoring Tan Trieu pomelo villages and traditional craft stories.', true),
  ('OBS-11-24', 'Ngày Văn hóa Việt Nam', 'Vietnam Culture Day', '24/11 hằng năm', '11-24', false, 2026, 'Kế hoạch thực hiện QĐ 1111/QĐ-TTg (19/06/2026) — Cổng Thông tin Chính phủ', 'https://cms.baochinhphu.vn/ke-hoach-to-chuc-ngay-van-hoa-viet-nam-giai-doan-2026-2030-102260620182703865.htm', 'vietnam_official', 'Mốc ngày 24/11/2026 đã qua theo đồng hồ hệ thống 25/11/2026 — chiến dịch kỷ niệm hiển thị ở chế độ Tóm tắt lại (Recap).', 'Observed annually on Nov 24 (past relative to Nov 25, 2026 reference clock — displayed as Recap).', true),
  ('OBS-12-05', 'Ngày Quốc tế Tình nguyện & Ngày Đất thế giới', 'International Volunteer Day & World Soil Day', '05/12 hằng năm', '12-05', false, 2026, 'UN International Volunteer Day & FAO World Soil Day', 'https://www.fao.org/world-soil-day/en/', 'un_fao', 'Cả hai ngày quốc tế cùng rơi vào 05/12 — NaiFarm đề xuất chuỗi hoạt động ''Ngày hội Nông sản & Thanh niên Đồng Nai'' (do NaiFarm tự tổ chức).', 'Both UN & FAO observances fall on Dec 5 — aligned with NaiFarm''s self-organized Youth & Soil showcase.', true),
  ('OBS-LUNAR-TET', 'Tết Nguyên đán & Lễ hội Truyền thống (Âm lịch — cần xác minh theo năm)', 'Lunar New Year & Mid-Autumn Festival (Verify lunar calendar annually)', 'Theo lịch Âm chính thức từng năm', 'LUNAR-VERIFY', true, 2026, 'Thông báo lịch nghỉ lễ hằng năm của cơ quan có thẩm quyền', 'https://baochinhphu.vn/', 'traditional_lunar', 'Ngày Âm lịch thay đổi theo năm dương lịch — không dùng công thức lặp RRULE dương để tự tính.', 'Lunar observance dates vary annually and must be verified against official year schedules.', true)
