values
  ('CMP-2026-CULTURE-RECAP', 'huong-vi-va-ban-sac-dong-nai-recap', 'Hương vị và Bản sắc Đồng Nai (Tóm tắt dịp 23–24/11)', 'Dong Nai Heritage & Flavor Recap (Nov 23–24)', 'Đã diễn ra nhân Ngày Di sản 23/11 & Ngày Văn hóa Việt Nam 24/11 — tổng hợp câu chuyện nhà vườn & bài học song ngữ.', 'Concluded cultural series celebrating Heritage Day (Nov 23) & Vietnam Culture Day (Nov 24).', 'Lưu giữ câu chuyện làng bưởi Tân Triều, chôm chôm Long Khánh và bài học giải phẫu nông sản 2D.', 'Preserve orchard stories from Tan Trieu & Long Khanh alongside bilingual heritage lessons.', 'cultural_recap', 'NaiFarm (Kịch bản văn hóa cộng đồng)', '{domestic_customer,international_guest,adult_member}', 'ended', '2026-11-23T08:00:00+07:00', '2026-11-24T22:00:00+07:00', 'Asia/Ho_Chi_Minh', 2, true, '/images/stitch/stitch-19.jpg', 'Vườn bưởi Tân Triều xanh mát ven sông Đồng Nai dịp Ngày Di sản & Văn hóa', 'Lush Tan Trieu pomelo grove featured in the Nov 23–24 cultural recap', 'Xem tổng kết câu chuyện & bài học', 'View Heritage Recap & Lessons', '/events/huong-vi-va-ban-sac-dong-nai-recap', 'Minh Anh (TNV Văn hóa)', 'Thu Hà (Điều phối W04)', '{P06,P07,P01,P08}', '{farm-ba-minh-tan-trieu,farm-ba-tu-demo}', '{mot-ngay-lam-nong-dan-cu-lao-chu-ba-minh}', '{NF-LIVE-REPLAY-TT}', '{cau-tao-buoi-da-xanh-tan-trieu,b1-green-farm-culture-and-field-lab}', '{PROMO-HERITAGE-ENDED}', 8000000, 6200000, 420, 48, 18600000, '[{"time":"23/11 · 09:00","titleVi":"Phát lại ghi hình cắt bưởi Tân Triều cùng Chú Ba Minh","titleEn":"Illustrated Replay: Pomelo Harvest at Tan Trieu","route":"/live/NF-LIVE-REPLAY-TT"},{"time":"24/11 · 14:00","titleVi":"Ra mắt bài học song ngữ Văn hóa & Di sản vườn Đồng Nai","titleEn":"Published Bilingual Cultural Heritage Lesson","route":"/learn/b1-green-farm-culture-and-field-lab"}]', 'Trong hai ngày 23–24/11, chương trình ghi nhận các câu chuyện giữ giống bưởi đường lá cam cù lao Tân Triều và hướng dẫn quét QR lô NF-TT-2026-01 (dữ liệu mẫu đã kết thúc; không hiển thị đếm ngược).', 'Across November 23–24, this showcase highlighted Tan Trieu alluvial orchard stories and public QR verification on batch NF-TT-2026-01.'),
  ('CMP-2026-NOV-CONNECT', 'tiep-noi-ngay-van-hoa-dac-san-dong-nai-ket-noi-nha-vuon', 'Tiếp nối Ngày Văn hóa Việt Nam · Đặc sản Đồng Nai kết nối nhà vườn', 'Continuing Cultural Heritage · Dong Nai Specialties Connect Farmers', 'Chiến dịch nền tảng NaiFarm từ 25/11 đến 30/11/2026: ưu đãi nhận hàng tại vườn, trải nghiệm miệt vườn cuối tuần và lịch học Đại sứ Thanh niên.', 'Active platform initiative (Nov 25–30): seasonal orchard baskets, bilingual agritourism tours, and youth ambassador sessions.', 'Kích cầu nông sản đang vào mùa, thúc đẩy nhận hàng tại vườn giảm bao bì nhựa và giới thiệu lịch tour cuối tuần.', 'Promote in-season orchard goods, encourage direct farm pickup, and fill weekend bilingual tour slots.', 'platform_initiative', 'NaiFarm (Tổ điều phối & HTX liên kết)', '{domestic_customer,international_guest,adult_member}', 'active', '2026-11-25T00:00:00+07:00', '2026-11-30T23:59:00+07:00', 'Asia/Ho_Chi_Minh', 1, true, '/images/stitch/stitch-02.jpg', 'Nông sản Đồng Nai đặc trưng vùng Tân Triều và Long Khánh kết nối trực tiếp nhà vườn', 'Dong Nai specialty pomelo and rambutan orchards connecting directly with visitors', 'Khám phá đặc sản & Ưu đãi 25–30/11', 'Explore Nov 25–30 Showcase', '/events/tiep-noi-ngay-van-hoa-dac-san-dong-nai-ket-noi-nha-vuon', 'Bộ phận Marketing HTX Tân Triều', 'Quản trị Nội dung W06', '{P01,P04,P06,P07,P08,P11}', '{farm-ba-tu-demo,farm-ba-minh-tan-trieu,farm-htx-xuan-loc}', '{mot-ngay-lam-nong-dan-cu-lao-chu-ba-minh,tham-quan-vuon-ba-tu-long-khanh}', '{NF-LIVE-01,NF-LIVE-02}', '{a1-hello-from-dong-nai-bilingual,a2-responsible-product-guide}', '{PROMO-HTXTANTRIEU,PROMO-DANGBAN25}', 15000000, 6850000, 540, 64, 24500000, '[{"time":"28/11 · 08:30","titleVi":"Ca tham quan cuối tuần Vườn Chú Ba Minh & Chú Ba Tư","titleEn":"Weekend Bilingual Orchard Tour Slots","route":"/explore?view=tours"},{"time":"28/11 · 09:00","titleVi":"Lịch Livestream Ghé vườn Ba Tư · Lô NF-DEMO-001","titleEn":"Scheduled Live Story: Uncle Ba Tu''''s Orchard","route":"/live/NF-LIVE-01"},{"time":"30/11 · 14:30","titleVi":"Livestream Xưởng rang hạt điều HTX Xuân Lộc","titleEn":"Scheduled Live: Xuan Loc Cashew Roastery","route":"/live/NF-LIVE-02"}]', , ),
  ('CMP-2026-DEC-YOUTH-SOIL', 'ngay-hoi-nong-san-va-thanh-nien-05-12', 'Ngày hội Nông sản & Thanh niên Đồng Nai (Hưởng ứng 05/12 Quốc tế Tình nguyện & Ngày Đất)', 'Dong Nai Youth & Sustainable Soil Fair (Aligned with Dec 5 Observances)', 'Chương trình do NaiFarm tự xây dựng kịch bản chuẩn bị cho ngày 05/12/2026 (08:30 – 19:00): tour trải nghiệm, hội thảo đất sạch, quiz Đại sứ và ghi nhận giờ tình nguyện.', 'Self-organized NaiFarm community program aligned with UN International Volunteer Day & FAO World Soil Day (Dec 5, 08:30–19:00 ICT).', 'Kết nối thanh niên đón khách quốc tế, thực hành giảm lãng phí thực phẩm NaiRescue và cập nhật nhật ký đất vườn.', 'Engage youth ambassadors in farm tours, soil literacy workshops, and verified volunteer hour tracking.', 'platform_initiative', 'NaiFarm (Chương trình tự tổ chức — không gắn danh nghĩa cơ quan/UN)', '{domestic_customer,international_guest,adult_member,organization}', 'scheduled', '2026-12-01T08:00:00+07:00', '2026-12-05T21:30:00+07:00', 'Asia/Ho_Chi_Minh', 1, false, '/images/stitch/stitch-30.jpg', 'Thanh niên tình nguyện và nhà nông Đồng Nai chuẩn bị Ngày hội 05/12', 'Youth volunteers and Dong Nai orchard owners preparing for Dec 5 Youth & Soil Fair', 'Xem lịch trình 05/12 & Nhiệm vụ chuẩn bị', 'View Dec 5 Agenda & Volunteer Tasks', '/events/ngay-hoi-nong-san-va-thanh-nien-05-12', 'Thu Hà (Điều phối W04)', 'Quản trị Nền tảng W06', '{P06,P01,P08,P09}', '{farm-ba-minh-tan-trieu,farm-ba-tu-demo,farm-tan-an-buoi}', '{mot-ngay-lam-nong-dan-cu-lao-chu-ba-minh,trai-nghiem-xuong-rang-hat-dieu-xuan-loc}', '{NF-LIVE-01}', '{b1-green-farm-culture-and-field-lab,a2-welcome-to-the-farm-tour-guide}', '{PROMO-RESCUE-DEC}', 12000000, 0, 0, 0, 0, '[{"time":"05/12 · 08:30","titleVi":"Tour vườn & thực hành bài học Ngày Đất thế giới","titleEn":"08:30 ICT · Orchard Walk & Soil Literacy Lesson","route":"/explore?view=tours"},{"time":"05/12 · 10:00","titleVi":"Phiên giới thiệu đặc sản & quét QR truy xuất tại gian hàng","titleEn":"10:00 ICT · Specialty Showcase & Live QR Demo","route":"/marketplace"},{"time":"05/12 · 14:00","titleVi":"Workshop đóng gói xanh & Quiz Đại sứ Thanh niên Toàn cầu","titleEn":"14:00 ICT · Eco Packaging Workshop & Ambassador Quiz","route":"/learn/b1-green-farm-culture-and-field-lab"},{"time":"05/12 · 19:00","titleVi":"Phiên tổng kết lịch phát sóng & ghi nhận giờ TNV hợp lệ","titleEn":"19:00 ICT · Evening Recap & Volunteer Hours Log","route":"/live"}]', , ),
  ('CMP-2026-1212-FAIR', 'phien-cho-12-12-va-qua-tang-cuoi-nam', 'Phiên chợ Cuối năm 12/12 & Hộp quà Đặc sản Đồng Nai (Chiến dịch thương mại)', 'Year-End Dec 12 Harvest Box & Gift Campaign (Commercial Schedule)', 'Đợt ưu đãi thương mại do các HTX lựa chọn cho ngày 12/12/2026 — kiểm tra tồn kho thực tế trước khi mở.', 'Scheduled cooperative gift box promotion starting Dec 12 (strictly scheduled, not active before start time).', 'Mở bán hộp quà NaiBox 95 và điều phối lịch giao hàng cuối năm qua HTX Tân Triều.', 'Launch NaiBox 95 year-end gift sets with validated warehouse stock allocation.', 'commercial', 'HTX Tân Triều & Khối Đối tác W05', '{domestic_customer,organization}', 'scheduled', '2026-12-12T00:00:00+07:00', '2026-12-15T23:59:00+07:00', 'Asia/Ho_Chi_Minh', 3, false, '/images/stitch/stitch-31.jpg', 'Hộp quà đặc sản NaiBox 95 đóng gói gọn gàng chuẩn bị cho phiên cuối năm', 'NaiBox 95 Đồng Nai year-end specialty gift box assortment', 'Xem trước điều kiện ưu đãi 12/12', 'Preview Dec 12 Offer Rules', '/events/phien-cho-12-12-va-qua-tang-cuoi-nam', 'Kinh doanh HTX Tân Triều', 'Ban Chủ nhiệm HTX Tân Triều', '{P08,P11}', '{farm-ba-minh-tan-trieu,farm-htx-xuan-loc}', '{trai-nghiem-xuong-rang-hat-dieu-xuan-loc}', '{NF-LIVE-02}', '{a1-farm-market-english}', '{PROMO-1212-UPCOMING}', 10000000, 0, 0, 0, 0, '[{"time":"12/12 · 00:00","titleVi":"Mở áp dụng ưu đãi Hộp quà Cuối năm (theo ngân sách giới hạn)","titleEn":"12/12 · Scheduled Promo Rules Open","route":"/events?tab=deals"}]', , ),
